def table(headers,rows):
    return '\n'+'| '+' | '.join(headers)+' |\n| '+' | '.join(['---']*len(headers))+' |\n'+''.join('| '+' | '.join(str(x) for x in r)+' |\n' for r in rows)+'\n'
def short(t):return t.split('.')[2]+'/'+t.split('.')[-1]
def f(x,n=6):return f'{float(x):.{n}f}'
def ci(x,n=6,factor=1):return '['+', '.join(f(v*factor,n) for v in x)+']'

